const salary = Number(annualSalary) || 0;
const cPct = (Number(contributionPct) || 0) / 100;
const mPct = (Number(employerMatchPct) || 0) / 100;
const yrs = Number(years) || 0;
const r = 0.07;
const annualSelf = salary * cPct;
const annualMatch = salary * Math.min(mPct, cPct);
const annualTotal = annualSelf + annualMatch;
const fv = r > 0 ? annualTotal * ((Math.pow(1 + r, yrs) - 1) / r) : annualTotal * yrs;
const totalContributed = annualTotal * yrs;
const matchShare = totalContributed > 0 ? (annualMatch * yrs / totalContributed) * 100 : 0;
return { matchShare, fv, totalContributed, annualMatch };

